// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        depositAmount = bound(depositAmount, 1, 100 ether);
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        address recipient = makeAddr("recipient");
        uint256 recipientBalanceBefore = recipient.balance;
        c.migrateTo(recipient);
        uint256 recipientBalanceAfter = recipient.balance;
        assertTrue(recipientBalanceAfter - recipientBalanceBefore == balanceBefore);
    }
}

